1	// Package money handles amounts of money. An amount is an int64 count of its currency's minor unit (cents for USD), never a
2	// float.
3	package money
4	
5	import (
6		"errors"
7		"fmt"
8		"strconv"
9		"strings"
10	)
11	
12	// Currency is an ISO 4217 currency code.
13	type Currency string
14	
15	// The currencies Tally bills in.
16	const (
17		USD Currency = "USD"
18		EUR Currency = "EUR"
19		GBP Currency = "GBP"
20		JPY Currency = "JPY"
21		KWD Currency = "KWD"
22	)
23	
24	var symbols = map[Currency]string{USD: "$", EUR: "€", GBP: "£", JPY: "¥", KWD: "KWD "}
25	
26	// decimals is each currency's number of minor-unit digits after the decimal point (ISO 4217).
27	var decimals = map[Currency]int{USD: 2, EUR: 2, GBP: 2, JPY: 0, KWD: 3}
28	
29	// Valid reports whether c is a currency Tally bills in.
30	func (c Currency) Valid() bool {
31		_, ok := symbols[c]
32		return ok
33	}
34	
35	// MinorUnits returns how many decimal places c has: 2 for USD, 0 for JPY, 3 for KWD. An unknown currency has 2.
36	func (c Currency) MinorUnits() int {
37		if d, ok := decimals[c]; ok {
38			return d
39		}
40		return 2
41	}
42	
43	// ErrInvalidAmount is returned for an amount that cannot be read.
44	var ErrInvalidAmount = errors.New("invalid amount")
45	
46	// ParseMajor reads an amount a person typed in major units ("12.50", "7") and returns it in minor units. It takes at most
47	// the currency's decimals and pads fewer: "12.5" USD is 1250, "7" KWD is 7000, and JPY takes no decimal point at all.
48	func ParseMajor(s string, c Currency) (int64, error) {
49		if !c.Valid() {
50			return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
51		}
52		d := c.MinorUnits()
53		s = strings.TrimSpace(s)
54		whole, frac, hasDot := strings.Cut(s, ".")
55		if whole == "" || (hasDot && (frac == "" || d == 0)) || len(frac) > d {
56			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
57		}
58		for _, r := range whole + frac {
59			if r < '0' || r > '9' {
60				return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
61			}
62		}
63		frac += strings.Repeat("0", d-len(frac))
64		n, err := strconv.ParseInt(whole+frac, 10, 64)
65		if err != nil {
66			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
67		}
68		return n, nil
69	}
70	
71	// Format renders an amount for people, with the currency's decimals: "$1,234.50", "-€0.99", "¥1,000", "KWD 1.250".
72	func Format(amount int64, c Currency) string {
73		sign, whole, frac := split(amount, c)
74		return sign + symbols[c] + group(whole) + frac
75	}
76	
77	// Major renders an amount in major units for people to type and read, with the currency's decimals and no thousands
78	// separator: "12.50", "1000", "1.250", "-5".
79	func Major(amount int64, c Currency) string {
80		sign, whole, frac := split(amount, c)
81		return sign + strconv.FormatInt(whole, 10) + frac
82	}
83	
84	// split breaks an amount into its sign, its whole major units, and its fraction (".50", or "" for a currency with no
85	// decimals).
86	func split(amount int64, c Currency) (sign string, whole int64, frac string) {
87		if amount < 0 {
88			sign, amount = "-", -amount
89		}
90		d := c.MinorUnits()
91		p := int64(1)
92		for range d {
93			p *= 10
94		}
95		whole = amount / p
96		if d == 0 {
97			return sign, whole, ""
98		}
99		return sign, whole, fmt.Sprintf(".%0*d", d, amount%p)
100	}
101	
102	// group writes n with a comma between each group of three digits.
103	func group(n int64) string {
104		s := strconv.FormatInt(n, 10)
105		var b strings.Builder
106		for i, r := range s {
107			if i > 0 && (len(s)-i)%3 == 0 {
108				b.WriteByte(',')
109			}
110			b.WriteRune(r)
111		}
112		return b.String()
113	}
114	
115	// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
116	func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }
117	
118	// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
119	func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }
120	
121	// divRound divides and rounds half away from zero.
122	func divRound(num, den int64) int64 {
123		if (num < 0) != (den < 0) {
124			return -((abs(num) + abs(den)/2) / abs(den))
125		}
126		return (abs(num) + abs(den)/2) / abs(den)
127	}
128	
129	func abs(v int64) int64 {
130		if v < 0 {
131			return -v
132		}
133		return v
134	}
